# Homebrew formula for obscura.
#
# GENERATED by rules_brew -- do not edit by hand;
# the next release overwrites this file.
class Obscura < Formula
  desc "Headless browser engine: CDP and MCP servers, fetch and scrape CLI"
  homepage "https://github.com/qzmfranklin/homebrew-tap"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/obscura-0.2.4/obscura-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/obscura-0.2.4/obscura-linux-amd64.tar.xz",
    ),
  )
  version "0.2.4"
  sha256 on_system_conditional(
    macos: "ba4862a1aab10912717ca9268f65aa3c64172a0918e5f1e4cc975b642294f5ae",
    linux: on_arch_conditional(
      intel: "1611db10eacf672f086a8dab50a530e72819602faab8a29d0b2b72d0bbfc6179",
    ),
  )
  license "Apache-2.0"

  def install
    # Two binaries, one install: the scrape path spawns obscura-worker from
    # beside the main binary (current_exe().parent()/obscura-worker), so both
    # must land in the keg's bin — bin.install links them into
    # HOMEBREW_PREFIX/bin together.
    bin.install "obscura"
    bin.install "obscura-worker"

    # Ad-hoc codesign on macOS for BOTH binaries. This is INTENTIONAL and
    # load-bearing, not a workaround: the binaries are unsigned, and macOS
    # refuses to exec an unsigned or stale-signed Mach-O. Writing the file also
    # invalidates any prior signature, so each must be re-signed after install.
    # (The renderer's generated adhoc_sign block signs only the single `bin`;
    # this recipe carries two, so the block is spelled out here over the pair —
    # adhoc_sign = False on the rule.)
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      ["obscura", "obscura-worker"].each do |b|
        chmod 0755, bin/b
        system "/usr/bin/xattr", "-cr", bin/b
        system "/usr/bin/codesign", "--force", "--sign", "-", bin/b
      end
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/obscura"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew obscura at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed obscura is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"obscura") unless linked.symlink?
  end


  def caveats
    mac = on_macos do
      <<~EOS
        Two binaries install side by side: `obscura` (the CLI — CDP and MCP
        servers, fetch/scrape) and `obscura-worker`, spawned internally by
        `obscura scrape` (nothing to run or configure by hand).

        Rendering uses your system's own font collection — no fonts are bundled
        and none are required beyond what macOS ships.

        The published binaries are ad-hoc signed, not notarized. Homebrew strips
        the quarantine attribute on install, so they run when installed through
        brew; a binary downloaded directly from the release page may additionally
        need `xattr -cr <path>` before macOS will exec it.
      EOS
    end
    linux = on_linux do
      <<~EOS
        Two binaries install side by side: `obscura` (the CLI — CDP and MCP
        servers, fetch/scrape) and `obscura-worker`, spawned internally by
        `obscura scrape` (nothing to run or configure by hand).

        The binaries are built against an Ubuntu 22.04 sysroot, so the minimum
        system glibc is 2.35 (ubuntu22+). On hosts with glibc < 2.39 (Ubuntu 22.04
        and older), Homebrew's own linux layer injects gcc and glibc as implicit
        dependencies to EVERY formula and builds them from source — this formula
        carries no real dependencies (a prebuilt tarball and an install block), so
        ignore the synthetic ones:

            brew install --ignore-dependencies qzmfranklin/tap/obscura

        A host older than glibc 2.35 fails on its own with a self-explanatory
        loader error.
      EOS
    end
    mac || linux
  end

  test do
    # Cheap smokes only: --version exercises the full load path (the binary
    # links V8 and the stealth-transport BoringSSL) without spawning any
    # engine, network fetch, or worker process; the worker gets a --help
    # check (its CLI surface), likewise spawn-free.
    assert_match(/0\.2\.4/, shell_output("#{bin}/obscura --version"))
    assert_match(/Usage:|obscura-worker/, shell_output("#{bin}/obscura-worker --help"))
  end
end
